create or replace function private.request_mission_approval(p_mission_id uuid,p_action_id uuid,p_scope jsonb) returns public.mission_approvals language plpgsql security definer set search_path='pg_catalog','public' as $$ declare v_mission public.missions; v_approval public.mission_approvals; begin if auth.uid() is null then raise exception 'AUTHENTICATION_REQUIRED' using errcode='42501'; end if; if p_scope is null or jsonb_typeof(p_scope)<>'object' then raise exception 'INVALID_APPROVAL_SCOPE' using errcode='22023'; end if; select * into v_mission from public.missions where id=p_mission_id for update; if not found or not private.can_edit_workspace(v_mission.workspace_id,auth.uid()) then raise exception 'MISSION_NOT_FOUND_OR_FORBIDDEN' using errcode='42501'; end if; if p_action_id is not null and not exists(select 1 from public.mission_actions where id=p_action_id and mission_id=p_mission_id) then raise exception 'ACTION_NOT_FOUND_OR_FORBIDDEN' using errcode='42501'; end if; if exists(select 1 from public.mission_approvals where mission_id=p_mission_id and status='PENDING') then raise exception 'APPROVAL_ALREADY_PENDING' using errcode='22023'; end if; insert into public.mission_approvals(mission_id,workspace_id,action_id,requested_by,status,requested_scope) values(v_mission.id,v_mission.workspace_id,p_action_id,auth.uid(),'PENDING',p_scope) returning * into v_approval; perform public.record_mission_event(v_mission.id,'APPROVAL_REQUESTED',jsonb_build_object('approval_id',v_approval.id,'action_id',p_action_id,'requested_by',auth.uid())); return v_approval; end; $$;
create or replace function private.decide_mission_approval(p_approval_id uuid,p_decision text,p_note text default null) returns public.mission_approvals language plpgsql security definer set search_path='pg_catalog','public' as $$ declare v_approval public.mission_approvals; begin if auth.uid() is null then raise exception 'AUTHENTICATION_REQUIRED' using errcode='42501'; end if; if p_decision not in('APPROVED','REJECTED','CANCELLED') then raise exception 'INVALID_APPROVAL_DECISION' using errcode='22023'; end if; select * into v_approval from public.mission_approvals where id=p_approval_id for update; if not found or private.workspace_role(v_approval.workspace_id) not in('owner','admin') then raise exception 'APPROVAL_NOT_FOUND_OR_FORBIDDEN' using errcode='42501'; end if; if v_approval.status<>'PENDING' then raise exception 'APPROVAL_ALREADY_DECIDED' using errcode='22023'; end if; update public.mission_approvals set status=p_decision,decided_by=auth.uid(),decision_note=nullif(btrim(coalesce(p_note,'')),''),decided_at=timezone('utc',now()) where id=v_approval.id returning * into v_approval; perform public.record_mission_event(v_approval.mission_id,'APPROVAL_DECIDED',jsonb_build_object('approval_id',v_approval.id,'status',v_approval.status,'decided_by',auth.uid())); return v_approval; end; $$;
create or replace function public.request_mission_approval(p_mission_id uuid,p_action_id uuid,p_scope jsonb) returns public.mission_approvals language sql set search_path='pg_catalog','public' as $$ select private.request_mission_approval(p_mission_id,p_action_id,p_scope); $$;
create or replace function public.decide_mission_approval(p_approval_id uuid,p_decision text,p_note text default null) returns public.mission_approvals language sql set search_path='pg_catalog','public' as $$ select private.decide_mission_approval(p_approval_id,p_decision,p_note); $$;
revoke all on function public.request_mission_approval(uuid,uuid,jsonb),public.decide_mission_approval(uuid,text,text) from public,anon;
grant execute on function public.request_mission_approval(uuid,uuid,jsonb),public.decide_mission_approval(uuid,text,text) to authenticated;
revoke all on function private.request_mission_approval(uuid,uuid,jsonb),private.decide_mission_approval(uuid,text,text) from public,anon,authenticated;
grant execute on function private.request_mission_approval(uuid,uuid,jsonb),private.decide_mission_approval(uuid,text,text) to authenticated;